package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NumberUtils.isNumber to maximize branch and line coverage.
 */
public class NumberUtils_isNumber_TriageGen2Test {

    @Test
    public void testIsNumber_NullAndEmpty() {
        assertFalse("Null should return false", NumberUtils.isNumber(null));
        assertFalse("Empty string should return false", NumberUtils.isNumber(""));
    }

    @Test
    public void testIsNumber_Integers() {
        assertTrue(NumberUtils.isNumber("123"));
        assertTrue(NumberUtils.isNumber("-123"));
        assertTrue(NumberUtils.isNumber("0"));
        assertTrue(NumberUtils.isNumber("0123"));
    }

    @Test
    public void testIsNumber_Hexadecimal() {
        assertTrue(NumberUtils.isNumber("0x123"));
        assertTrue(NumberUtils.isNumber("0xABC"));
        assertTrue(NumberUtils.isNumber("0xabc"));
        assertTrue(NumberUtils.isNumber("0x1a2B3C"));
        assertTrue(NumberUtils.isNumber("-0x123"));

        assertFalse("Invalid hex prefix", NumberUtils.isNumber("0x"));
        assertFalse("Invalid hex char", NumberUtils.isNumber("0xG12"));
        assertFalse("Invalid hex char lowercase", NumberUtils.isNumber("0x12g"));
    }

    @Test
    public void testIsNumber_Decimals() {
        assertTrue(NumberUtils.isNumber("123.456"));
        assertTrue(NumberUtils.isNumber(".456"));
        assertTrue(NumberUtils.isNumber("123."));
        assertTrue(NumberUtils.isNumber("-123.456"));

        assertFalse("Two decimal points", NumberUtils.isNumber("12.34.56"));
        assertFalse("Decimal in exponent", NumberUtils.isNumber("12e3.4"));
    }

    @Test
    public void testIsNumber_Exponents() {
        assertTrue(NumberUtils.isNumber("123e456"));
        assertTrue(NumberUtils.isNumber("123E456"));
        assertTrue(NumberUtils.isNumber("123e+456"));
        assertTrue(NumberUtils.isNumber("123e-456"));
        assertTrue(NumberUtils.isNumber("-123e456"));

        assertFalse("No digit before E", NumberUtils.isNumber("e456"));
        assertFalse("No digit after E sign", NumberUtils.isNumber("123e+"));
        assertFalse("Two E's", NumberUtils.isNumber("123e456e"));
        assertFalse("E at end", NumberUtils.isNumber("123e"));
    }

    @Test
    public void testIsNumber_TypeQualifiers() {
        // Testing d, D, f, F
        assertTrue(NumberUtils.isNumber("123d"));
        assertTrue(NumberUtils.isNumber("123D"));
        assertTrue(NumberUtils.isNumber("123f"));
        assertTrue(NumberUtils.isNumber("123F"));

        // Testing l, L
        assertTrue(NumberUtils.isNumber("123l"));
        assertTrue(NumberUtils.isNumber("123L"));

        // Invalid qualifiers
        assertFalse("E with L", NumberUtils.isNumber("123e456L"));
        assertFalse("E with l", NumberUtils.isNumber("123e456l"));
        assertFalse("Invalid qualifier", NumberUtils.isNumber("123x"));

        // Check foundDigit requirement for qualifiers
        assertFalse("Just a dot with qualifier", NumberUtils.isNumber(".f"));
    }

    @Test
    public void testIsNumber_EdgeCases() {
        // Testing the loop logic with allowSigns and foundDigit
        // Case: "123E-" (allowSigns is true, foundDigit is false after E sign)
        // The logic i < sz + 1 && allowSigns && !foundDigit handles trailing signs in some contexts
        // but the final return checks !allowSigns && foundDigit
        assertFalse("Trailing sign after E", NumberUtils.isNumber("123e-"));

        // Testing the logic for single character or specific boundary conditions
        assertFalse("Just a sign", NumberUtils.isNumber("-"));
        assertFalse("Just a dot", NumberUtils.isNumber("."));

        // Complex valid case
        assertTrue(NumberUtils.isNumber("123.456e-789F"));
    }

    @Test
    public void testIsNumber_SpecificBranchCoverage() {
        // Branch: chars[0] == '-' but sz is not > start + 1
        // This happens if str is exactly "-"
        assertFalse(NumberUtils.isNumber("-"));

        // Branch: (chars[i] < '0' || chars[i] > '9') && (chars[i] < 'a' || ...) inside hex loop
        assertFalse(NumberUtils.isNumber("0x12!3"));

        // Branch: !allowSigns && (chars[i] == 'd' || ...)
        // This requires foundDigit to be true
        assertTrue(NumberUtils.isNumber("1d"));

        // Branch: chars[i] == 'l' || chars[i] == 'L'
        // Requires foundDigit && !hasExp
        assertTrue(NumberUtils.isNumber("1L"));
        assertFalse(NumberUtils.isNumber("1e2L"));
    }
}
